CREATE TABLE IF NOT EXISTS room_bans(room_id BIGINT REFERENCES rooms(id) ON DELETE CASCADE,user_id BIGINT REFERENCES users(id) ON DELETE CASCADE,reason TEXT NOT NULL DEFAULT '',banned_by BIGINT REFERENCES users(id) ON DELETE SET NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY(room_id,user_id));
CREATE TABLE IF NOT EXISTS room_mutes(room_id BIGINT REFERENCES rooms(id) ON DELETE CASCADE,user_id BIGINT REFERENCES users(id) ON DELETE CASCADE,muted_until TIMESTAMPTZ,reason TEXT NOT NULL DEFAULT '',muted_by BIGINT REFERENCES users(id) ON DELETE SET NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY(room_id,user_id));
CREATE TABLE IF NOT EXISTS user_blocks(blocker_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,blocked_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY(blocker_id,blocked_id),CHECK(blocker_id<>blocked_id));
CREATE TABLE IF NOT EXISTS reports(id BIGSERIAL PRIMARY KEY,reporter_id BIGINT REFERENCES users(id) ON DELETE SET NULL,target_type TEXT NOT NULL,target_id BIGINT NOT NULL,reason TEXT NOT NULL,details TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'open',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),reviewed_at TIMESTAMPTZ,reviewed_by BIGINT REFERENCES users(id) ON DELETE SET NULL);
CREATE INDEX IF NOT EXISTS reports_status_idx ON reports(status,id DESC);
CREATE TABLE IF NOT EXISTS profile_privacy(user_id BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,who_can_message TEXT NOT NULL DEFAULT 'friends',who_can_add TEXT NOT NULL DEFAULT 'everyone',show_last_seen BOOLEAN NOT NULL DEFAULT TRUE,show_city BOOLEAN NOT NULL DEFAULT TRUE,updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS user_sessions(session_hash TEXT PRIMARY KEY,user_id BIGINT REFERENCES users(id) ON DELETE CASCADE,user_agent TEXT NOT NULL DEFAULT '',ip_address TEXT NOT NULL DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),last_seen TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS push_subscriptions(id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES users(id) ON DELETE CASCADE,endpoint TEXT NOT NULL UNIQUE,p256dh TEXT NOT NULL,auth TEXT NOT NULL,user_agent TEXT NOT NULL DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS message_reads(kind TEXT NOT NULL CHECK(kind IN('room','direct')),scope_id BIGINT NOT NULL,user_id BIGINT REFERENCES users(id) ON DELETE CASCADE,last_message_id BIGINT NOT NULL DEFAULT 0,read_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY(kind,scope_id,user_id));
